targets.expr:
max by (cluster, tier) (
  label_replace(
    1 - elasticsearch_filesystem_data_available_bytes{namespace="logging", cluster=~"$cluster", name=~".*-data-(hot|warm|cold)-.*"} / elasticsearch_filesystem_data_size_bytes{namespace="logging", cluster=~"$cluster", name=~".*-data-(hot|warm|cold)-.*"}
  , "tier", "$1", "name", ".*-data-(hot|warm|cold)-.*")
)

sum by (namespace) (
  label_replace(
    avg_over_time(sum by (cluster, exported_namespace) (rate(vector_log_counter{cluster=~"$cluster"}[1h]))[7d:1h])
  , "namespace", "$1", "exported_namespace", "(.*)"
  )
) * 86400 > 0

sum by (namespace) (
  label_replace(
    avg_over_time(sum by (cluster, exported_namespace) (rate(vector_log_counter{cluster=~"$cluster"}[1h]))[7d:1h]) * 604800
  , "namespace", "$1", "exported_namespace", "(.*)"
  )
) > 0
